B.bAi={"\u062e\u0637\u0629 \u062a\u0634\u063a\u064a\u0644\u064a\u0629":0,"\u0639\u0627\u0645":1,"\u0631\u064a\u0627\u0636\u064a\u0627\u062a":2,"\u0639\u0644\u0648\u0645":3,"\u0644\u063a\u062a\u064a":4,"\u0627\u0646\u062c\u0644\u064a\u0632\u064a":5,"\u0625\u0633\u0644\u0627\u0645\u064a\u0627\u062a":6,"\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0627\u062a":7,"\u0641\u0646\u064a\u0629":8,"\u0628\u062f\u0646\u064a\u0629":9,"\u0631\u0642\u0645\u064a\u0629":10,"\u062d\u064a\u0627\u062a\u064a\u0629":11,"\u062a\u0641\u0643\u064a\u0631":12,"\u0646\u0634\u0627\u0637":13,"\u0631\u0648\u0628\u0648\u062a":14,"\u0642\u064a\u0645 \u0648\u0633\u0644\u0648\u0643":15,STEM:16,"\u0623\u062e\u0631\u0649":17}
B.bfA=s(["\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0644\u0637\u0644\u0627\u0628","\u0627\u0644\u062a\u0647\u064a\u0626\u0629 \u0627\u0644\u0625\u0631\u0634\u0627\u062f\u064a\u0629","\u0627\u062e\u062a\u0628\u0627\u0631 \u062a\u0634\u062e\u064a\u0635\u064a","\u0627\u0644\u062a\u0647\u064a\u0626\u0629 \u0648\u0627\u0644\u0627\u0633\u062a\u0639\u062f\u0627\u062f","\u062c\u0633\u0631 \u0627\u0644\u0643\u0644\u0645\u0627\u062a","\u0644\u063a\u062a\u064a \u062d\u064a\u0627\u062a\u064a","\u0627\u0644\u0644\u064a\u0627\u0642\u0629 \u0627\u0644\u0628\u062f\u0646\u064a\u0629","\u0627\u0644\u0643\u0631\u0627\u0633\u0629 \u0627\u0644\u0645\u0633\u0627\u0646\u062f\u0629 \u0641\u064a \u0627\u0644\u062e\u0637 \u0648\u0627\u0644\u0625\u0645\u0644\u0627\u0621"],t.s)
B.b2a=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0641\u0643\u0631 - \u0632\u0627\u0648\u062c - \u0634\u0627\u0631\u0643 \u0644\u062a\u0646\u0634\u064a\u0637 \u0627\u0644\u062d\u0648\u0627\u0631 (Think-Pair-Share).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0627\u0644\u0645\u0631\u0642\u0645\u0629 \u0627\u0644\u062a\u0639\u0627\u0648\u0646\u064a\u0629 (Numbered Heads Together).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0642\u0628\u0639\u0627\u062a \u0627\u0644\u0633\u062a \u0644\u0644\u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0645\u062a\u0648\u0627\u0632\u0646 (Six Thinking Hats).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0639\u0635\u0641 \u0627\u0644\u0630\u0647\u0646\u064a \u0648\u062a\u0648\u0644\u064a\u062f \u0627\u0644\u062d\u0644\u0648\u0644 (Brainstorming).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062c\u064a\u0643\u0633\u0648 \u0644\u0641\u0631\u0642 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u062a\u062e\u0635\u0635\u0629 (Jigsaw Technique).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0644\u0639\u0628 \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0648\u0627\u0644\u0645\u062d\u0627\u0643\u0627\u0629 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629 (Role Playing).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062c\u062f\u0648\u0644 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0630\u0627\u062a\u064a (K-W-L).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062e\u0631\u0627\u0626\u0637 \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0648\u0627\u0644\u062e\u0631\u0627\u0626\u0637 \u0627\u0644\u0630\u0647\u0646\u064a\u0629 (Mind Mapping).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0643\u0631\u0633\u064a \u0627\u0644\u0633\u0627\u062e\u0646 \u0644\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0633\u0631\u064a\u0639\u0629 (Hot Seat).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0623\u0639\u0648\u0627\u062f \u0627\u0644\u0645\u062b\u0644\u062c\u0627\u062a \u0644\u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0639\u0627\u062f\u0644 \u0648\u0627\u0644\u062d\u064a\u0627\u062f\u064a.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0628\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u062e\u0631\u0648\u062c \u0644\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a (Exit Tickets).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0623\u0642\u0631\u0627\u0646 \u0648\u0627\u0644\u0645\u0639\u0644\u0645 \u0627\u0644\u0635\u063a\u064a\u0631 (Peer Teaching).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0633\u0643\u0627\u0645\u0628\u0631 \u0644\u062a\u0648\u0644\u064a\u062f \u0627\u0644\u0623\u0641\u0643\u0627\u0631 \u0627\u0644\u0625\u0628\u062f\u0627\u0639\u064a\u0629 (SCAMPER).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0642\u0627\u0626\u0645 \u0639\u0644\u0649 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a (Problem-Based Learning).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0645\u0633\u0631\u062d\u0629 \u0627\u0644\u0645\u0646\u0627\u0647\u062c \u0648\u0627\u0644\u062f\u0631\u0627\u0645\u0627 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 (Educational Drama)."],t.s)
B.bsk=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062d\u0644 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0628\u062a\u0645\u062b\u064a\u0644 \u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0628\u0635\u0631\u064a\u0629 \u0648\u0627\u0644\u0631\u0633\u0648\u0645.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0627\u0644\u0623\u0646\u0645\u0627\u0637 \u0648\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0626\u064a \u0627\u0644\u0631\u064a\u0627\u0636\u064a.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u064a\u062f\u0648\u064a\u0627\u062a \u0648\u0627\u0644\u0645\u062d\u0633\u0648\u0633\u0627\u062a \u0641\u064a \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062a\u062e\u0645\u064a\u0646 \u0648\u0627\u0644\u062a\u062d\u0642\u0642 \u0627\u0644\u0645\u0646\u0637\u0642\u064a \u0641\u064a \u0627\u0644\u0645\u0639\u0627\u062f\u0644\u0627\u062a \u0627\u0644\u0645\u0639\u0642\u062f\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062d\u0644 \u0627\u0644\u0639\u0643\u0633\u064a \u0644\u0644\u0645\u0633\u0627\u0626\u0644 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629 \u0627\u0644\u0645\u0631\u0643\u0628\u0629."],t.s)
B.bt2=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062f\u0648\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u062e\u0645\u0627\u0633\u064a\u0629 (5Es: Engage, Explore, Explain, Elaborate, Evaluate).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0645\u062e\u062a\u0628\u0631\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u0642\u0635\u0627\u0626\u064a\u0629 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629 \u0648\u0627\u0644\u0645\u0648\u062c\u0647\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0631\u062d\u0644\u0627\u062a \u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0648\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629 \u0644\u0644\u0643\u0648\u0646 \u0648\u0627\u0644\u0637\u0628\u064a\u0639\u0629 (WebQuest).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0645\u062c\u0647\u0631\u064a\u0629 \u0627\u0644\u062f\u0642\u064a\u0642\u0629 \u0648\u062a\u062f\u0648\u064a\u0646 \u0627\u0644\u062e\u0635\u0627\u0626\u0635.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0628\u0646\u0627\u0621 \u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0644\u062a\u0648\u0636\u064a\u062d \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0627\u0644\u0645\u062c\u0631\u062f\u0629."],t.s)
B.bmh=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u062a\u0628\u0627\u062f\u0644\u064a\u0629 \u0627\u0644\u0645\u0639\u0645\u0642\u0629 \u0644\u0641\u0647\u0645 \u0627\u0644\u0645\u0642\u0631\u0648\u0621.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0645\u0633\u0631\u062d\u0629 \u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0634\u0639\u0631\u064a\u0629 \u0648\u0627\u0644\u0642\u0631\u0627\u0626\u064a\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0634\u062c\u0631\u0629 \u0627\u0644\u062c\u0630\u0648\u0631 \u0648\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0627\u0644\u0645\u0634\u062a\u0642\u0627\u062a \u0627\u0644\u0635\u0631\u0641\u064a\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062a\u0638\u0644\u064a\u0644 \u0627\u0644\u0644\u0648\u0646\u064a \u0644\u0644\u062a\u0645\u064a\u064a\u0632 \u0628\u064a\u0646 \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0646\u062d\u0648\u064a\u0629 \u0648\u0627\u0644\u0625\u0645\u0644\u0627\u0626\u064a\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062a\u0623\u0644\u064a\u0641 \u0627\u0644\u0642\u0635\u0635 \u0627\u0644\u062a\u0634\u0627\u0631\u0643\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0627\u062a."],t.s)
B.bfm=s(["Total Physical Response (TPR) Method.","Communicative Language Teaching (CLT).","Information Gap Activity for Paired Speaking.","Task-Based Language Learning (TBLL).","Phonics in Motion and Story Chanting."],t.s)
B.btx=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0646\u0628\u0627\u0637 \u0627\u0644\u0641\u0642\u0647\u064a \u0645\u0646 \u0627\u0644\u0623\u062f\u0644\u0629 \u0627\u0644\u0634\u0631\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0622\u0646\u064a\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0642\u0635\u0629 \u0627\u0644\u0642\u0631\u0622\u0646\u064a\u0629 \u0648\u0627\u0633\u062a\u062e\u0644\u0627\u0635 \u0627\u0644\u062f\u0631\u0648\u0633 \u0648\u0627\u0644\u0639\u0638\u0627\u062a.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0645\u062d\u0627\u0643\u0627\u0629 \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u0644\u0644\u0639\u0628\u0627\u062f\u0627\u062a (\u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0627\u0644\u0648\u0636\u0648\u0621\u060c \u0627\u0644\u062d\u062c).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062a\u0631\u062f\u064a\u062f \u0627\u0644\u0632\u0645\u0631\u0651\u064a \u0644\u0636\u0628\u0637 \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u062a\u062c\u0648\u064a\u062f."],t.s)
B.bkX=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062e\u0637 \u0627\u0644\u0632\u0645\u0646\u064a \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a \u0644\u0627\u0633\u062a\u0631\u062c\u0627\u0639 \u0627\u0644\u0648\u0642\u0627\u0626\u0639 \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u064a\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062f\u0631\u0627\u0633\u0629 \u0627\u0644\u062e\u0631\u0627\u0626\u0637 \u0627\u0644\u0637\u0628\u0648\u063a\u0631\u0627\u0641\u064a\u0629 \u0648\u062a\u062d\u0644\u064a\u0644 \u062f\u0644\u0627\u0644\u0627\u062a\u0647\u0627.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0644\u0639\u0628 \u0623\u062f\u0648\u0627\u0631 \u0627\u0644\u0634\u062e\u0635\u064a\u0627\u062a \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u064a\u0629 \u0627\u0644\u0648\u0637\u0646\u064a\u0629."],t.s)
B.bve=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062a\u0630\u0648\u0642 \u0627\u0644\u062c\u0645\u0627\u0644\u064a \u0648\u0627\u0644\u0646\u0642\u062f \u0627\u0644\u0641\u0646\u064a \u0627\u0644\u0645\u0648\u062c\u0647.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062a\u062c\u0631\u064a\u0628 \u0627\u0644\u062d\u0631 \u0628\u0627\u0644\u062e\u0627\u0645\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u0647\u0644\u0643\u0629 \u0648\u0627\u0644\u0637\u0628\u064a\u0639\u064a\u0629."],t.s)
B.bor=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u062f\u0627\u0626\u0631\u064a \u0648\u062a\u0646\u0645\u064a\u0629 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0644\u064a\u0627\u0642\u0629 \u0627\u0644\u0628\u062f\u0646\u064a\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0627\u0644\u062d\u0631\u0643\u064a\u0629 \u0627\u0644\u0628\u0637\u064a\u0626\u0629 \u0644\u0625\u062a\u0642\u0627\u0646 \u0627\u0644\u0645\u0647\u0627\u0631\u0629."],t.s)
B.boK=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0635\u0641 \u0627\u0644\u0645\u0642\u0644\u0648\u0628 \u0641\u064a \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0639\u0645\u0644\u064a \u0648\u0627\u0644\u062a\u0637\u0628\u064a\u0642\u064a.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062a\u0635\u062d\u064a\u062d \u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0623\u0643\u0648\u0627\u062f \u0627\u0644\u0628\u0631\u0645\u062c\u064a\u0629 (Debugging Challenges).","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629 \u0648\u0645\u0634\u0627\u0631\u064a\u0639 \u0627\u0644\u0648\u064a\u0628."],t.s)
B.b_T=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0645\u062d\u0627\u0643\u0627\u0629 \u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0648\u0625\u062f\u0627\u0631\u0629 \u0645\u064a\u0632\u0627\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0631\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0648\u0642\u062a \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u0648\u0644\u0648\u064a\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629."],t.s)
B.bt6=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0633\u0642\u0631\u0627\u0637\u064a\u0629 \u0627\u0644\u0639\u0645\u064a\u0642\u0629 \u0644\u0627\u0633\u062a\u062b\u0627\u0631\u0629 \u0627\u0644\u0639\u0642\u0644.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0645\u0646\u0637\u0642\u064a\u0629 \u0648\u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u0645\u063a\u0627\u0644\u0637\u0627\u062a."],t.s)
B.btJ=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0645\u0628\u0627\u062f\u0631\u0627\u062a \u0627\u0644\u0637\u0644\u0627\u0628\u064a\u0629 \u0648\u0627\u0644\u0645\u0634\u0627\u0631\u064a\u0639 \u0627\u0644\u0645\u064a\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u062a\u0637\u0648\u0639\u064a\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0645\u0633\u0627\u0628\u0642\u0627\u062a \u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0627\u0644\u062b\u0642\u0627\u0641\u064a\u0629 \u0627\u0644\u062d\u0645\u0627\u0633\u064a\u0629."],t.s)
B.bju=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062a\u062d\u062f\u064a \u0627\u0644\u062d\u0631\u0643\u064a \u0648\u062a\u0641\u0627\u062f\u064a \u0627\u0644\u0639\u0642\u0628\u0627\u062a \u0627\u0644\u0628\u0631\u0645\u062c\u064a\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0645\u062a\u0627\u0646\u0629 \u0627\u0644\u0645\u064a\u0643\u0627\u0646\u064a\u0643\u064a\u0629 \u0644\u0644\u062a\u0631\u0648\u0633 \u0648\u0627\u0644\u0645\u062d\u0631\u0643\u0627\u062a.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0636\u0628\u0637 \u0627\u0644\u062d\u0633\u0627\u0633\u0627\u062a \u0627\u0644\u0631\u0642\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0646\u0627\u0638\u0631\u064a\u0629 \u0628\u0627\u0644\u062a\u062c\u0631\u0628\u0629 \u0648\u0627\u0644\u062e\u0637\u0623."],t.s)
B.bbA=s(["\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u0627\u0644\u0623\u062e\u0644\u0627\u0642\u064a\u0629 \u0648\u0642\u0635\u0635 \u0627\u0644\u0645\u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0642\u064a\u0645\u064a\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0633\u0644\u0648\u0643 \u0627\u0644\u0625\u064a\u062c\u0627\u0628\u064a \u0628\u0627\u0644\u0623\u0642\u0631\u0627\u0646 \u0627\u0644\u0642\u062f\u0648\u0629.","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0628\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u0634\u0643\u0631 \u0648\u0627\u0644\u062a\u0642\u062f\u064a\u0631 \u0627\u0644\u0645\u062a\u0628\u0627\u062f\u0644\u0629 \u0641\u064a \u0627\u0644\u0635\u0641."],t.s)
B.bpM=s(["\u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0642\u0627\u0626\u0645 \u0639\u0644\u0649 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0647\u0646\u062f\u0633\u064a \u0648\u0627\u0644\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0639\u0645\u0644\u064a\u0629 (EDP).","\u062f\u0645\u062c \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0648\u0627\u0644\u0639\u0644\u0648\u0645 \u0644\u0627\u0628\u062a\u0643\u0627\u0631 \u062d\u0644 \u0644\u0645\u0634\u0643\u0644\u0629 \u0628\u064a\u0626\u064a\u0629 \u0648\u062a\u0637\u0628\u064a\u0642\u0647\u0627 \u0641\u064a \u0645\u062c\u0633\u0645.","\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u062c\u0633\u0645\u0627\u062a \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0623\u0628\u0639\u0627\u062f \u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u0641\u064a\u0632\u064a\u0627\u0621 \u0648\u0627\u0644\u0642\u0648\u0629.","\u062a\u0637\u0628\u064a\u0642 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0639\u0635\u0641 \u0627\u0644\u0630\u0647\u0646\u064a \u0627\u0644\u0647\u0646\u062f\u0633\u064a \u0627\u0644\u0645\u0642\u0644\u0648\u0628 (\u0647\u062f\u0645 \u0627\u0644\u0641\u0643\u0631\u0629 \u0648\u0628\u0646\u0627\u0624\u0647\u0627).","\u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u064a \u0627\u0644\u0631\u0642\u0645\u064a \u0644\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0637\u0628\u064a\u0639\u064a\u0629 \u0648\u0627\u0644\u0645\u062e\u0631\u062c\u0627\u062a \u0627\u0644\u062a\u062c\u0631\u064a\u0628\u064a\u0629."],t.s)
